<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$id=get_id();$st=mysqli_prepare($koneksi,"SELECT * FROM pengguna WHERE id_pengguna=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$d=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if(!$d)die('Pengguna tidak ditemukan.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$old=$d;$d['nama_lengkap']=trim($_POST['nama_lengkap']??'');$d['email']=trim($_POST['email']??'');$d['no_hp']=trim($_POST['no_hp']??'');$d['id_role']=(int)$_POST['id_role'];$d['id_fakultas']=$_POST['id_fakultas']!==''?(int)$_POST['id_fakultas']:null;$d['id_program_studi']=$_POST['id_program_studi']!==''?(int)$_POST['id_program_studi']:null;$d['status_aktif']=trim($_POST['status_aktif']??'Aktif');$password=$_POST['password']??'';if(!$d['nama_lengkap']||!$d['id_role'])$error='Nama dan role wajib diisi.';if(!$error){if($password!==''){$hash=password_hash($password,PASSWORD_DEFAULT);$st=mysqli_prepare($koneksi,"UPDATE pengguna SET id_role=?,id_fakultas=?,id_program_studi=?,nama_lengkap=?,email=?,no_hp=?,status_aktif=?,password_hash=? WHERE id_pengguna=?");mysqli_stmt_bind_param($st,'iiisssssi',$d['id_role'],$d['id_fakultas'],$d['id_program_studi'],$d['nama_lengkap'],$d['email'],$d['no_hp'],$d['status_aktif'],$hash,$id);}else{$st=mysqli_prepare($koneksi,"UPDATE pengguna SET id_role=?,id_fakultas=?,id_program_studi=?,nama_lengkap=?,email=?,no_hp=?,status_aktif=? WHERE id_pengguna=?");mysqli_stmt_bind_param($st,'iiissssi',$d['id_role'],$d['id_fakultas'],$d['id_program_studi'],$d['nama_lengkap'],$d['email'],$d['no_hp'],$d['status_aktif'],$id);}if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'pengguna',(string)$id,'UPDATE',$old,$d);flash('success','Pengguna berhasil diperbarui.');redirect_to('pengguna.php');}$error='Gagal memperbarui.';mysqli_stmt_close($st);}}$roles=mysqli_query($koneksi,"SELECT id_role,kode_role,nama_role FROM roles ORDER BY nama_role");$faks=mysqli_query($koneksi,"SELECT id_fakultas,nama_fakultas FROM fakultas ORDER BY nama_fakultas");$prodis=mysqli_query($koneksi,"SELECT ps.id_program_studi,ps.nama_program_studi,f.nama_fakultas FROM program_studi ps JOIN fakultas f ON ps.id_fakultas=f.id_fakultas ORDER BY f.nama_fakultas,ps.nama_program_studi");?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Pengguna</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">MANAJEMEN PENGGUNA</span><h1>Edit Pengguna</h1></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="dashboard-panel form-panel"><form method="post"><div class="form-grid"><div class="form-group"><label>Username</label><input value="<?=e($d['username'])?>" readonly></div><div class="form-group"><label>Nama Lengkap</label><input name="nama_lengkap" required value="<?=e($d['nama_lengkap'])?>"></div><div class="form-group"><label>Password Baru</label><input type="password" name="password" minlength="8" placeholder="Kosongkan jika tidak diubah"></div><div class="form-group"><label>Email</label><input type="email" name="email" value="<?=e($d['email'])?>"></div><div class="form-group"><label>No. HP</label><input name="no_hp" value="<?=e($d['no_hp'])?>"></div><div class="form-group"><label>Role</label><select name="id_role"><?php while($x=mysqli_fetch_assoc($roles)):?><option value="<?=$x['id_role']?>" <?=$d['id_role']==$x['id_role']?'selected':''?>><?=e($x['nama_role'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Fakultas</label><select name="id_fakultas"><option value="">-</option><?php while($x=mysqli_fetch_assoc($faks)):?><option value="<?=$x['id_fakultas']?>" <?=$d['id_fakultas']==$x['id_fakultas']?'selected':''?>><?=e($x['nama_fakultas'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Program Studi</label><select name="id_program_studi"><option value="">-</option><?php while($x=mysqli_fetch_assoc($prodis)):?><option value="<?=$x['id_program_studi']?>" <?=$d['id_program_studi']==$x['id_program_studi']?'selected':''?>><?=e($x['nama_fakultas'].' - '.$x['nama_program_studi'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Status</label><select name="status_aktif"><option <?=$d['status_aktif']==='Aktif'?'selected':''?>>Aktif</option><option <?=$d['status_aktif']==='Tidak Aktif'?'selected':''?>>Tidak Aktif</option></select></div></div><div class="form-actions"><a class="btn btn-outline" href="pengguna.php">Batal</a><button class="btn btn-primary">Simpan Perubahan</button></div><?=csrf_field()?></form></div></main><script src="script.js"></script></body></html>